// Üretilen dosya: tool/ozgun/uret.py. Genel Kültür · Dinler tarihi ve inanç gelenekleri (tarafsız, bilgi düzeyinde) (zor).
const ozCulture7Zor = <(String, String, List<String>, String)>[
  ('\'Mana\' kavramı din biliminde neyi anlatmak için kullanılır?', 'Kişi ya da nesnelerde bulunduğuna inanılan doğaüstü gücü', ['Bir dinin kutsal kitaplarındaki ilk bölümü', 'Ölen kişinin ruhunun ayrıldıktan sonra gittiği yeraltı dünyasını', 'Bir tapınağın en kutsal iç odasını'], 'Mana, Pasifik (Melanezya ve Polinezya) dillerinden alınmış bir kavramdır; kişi, nesne ya da yerlerde bulunduğuna inanılan etkili, kişisel olmayan güç anlamına gelir.'),
  ('Karşılaştırmalı din biliminin kurucularından sayılan ve \'Doğu\'nun Kutsal Kitapları\' dizisini yayımlayan dilbilimci kimdir?', 'Max Müller', ['James Frazer', 'Sigmund Freud', 'Auguste Comte'], 'Alman asıllı Oxford\'lu dilbilimci Friedrich Max Müller, Doğu dinlerinin kutsal metinlerini İngilizceye kazandıran 50 ciltlik diziyi yönetmiş ve din bilimini ayrı bir alan olarak savunmuştur.'),
  ('Amerikalı psikolog William James\'in 1902\'de yayımlanan ve dinî deneyimi bireysel psikoloji açısından inceleyen eseri hangisidir?', 'Dinsel Deneyimin Çeşitleri', ['Kutsal ve Dindışı', 'Totem ve Tabu', 'Bir Yanılsamanın Geleceği adlı deneme'], 'William James\'in \'The Varieties of Religious Experience\' adlı eseri, dönüşüm, mistik deneyim ve azizlik gibi konuları bireysel yaşantılar üzerinden incelemiştir.'),
  ('Din biliminde \'fenomenolojik yaklaşım\' en iyi hangi tutumla tanımlanır?', 'İnananın deneyimini yargılamadan kendi anlamı içinde betimlemeye çalışmak', ['Dinlerin doğru ya da yanlış olduğunu mantıksal kanıtlarla göstermeye çalışmak', 'Dinleri yalnız ekonomik çıkarlarla açıklamak', 'Yalnız en eski metinleri geçerli kaynak saymak'], 'Fenomenolojik yaklaşım, doğruluk yargısını askıya alarak (epoche) dinî olguları inananın gözünden anlamaya ve betimlemeye çalışır.'),
  ('Yahudi mistik geleneğinin adı ve onunla ilişkilendirilen başlıca eser hangisidir?', 'Kabala - Zohar', ['Hasidizm - Mişna', 'Talmud - Siddur', 'Midraş - Tanah'], 'Kabala Yahudi mistisizminin adıdır; 13. yüzyıl İspanya\'sında ortaya çıkan Zohar bu geleneğin temel eseridir.'),
  ('Kaşrut kurallarında \'parve\' olarak nitelenen yiyecekler hangi özelliği taşır?', 'Ne et ne süt sayıldığı için her ikisiyle de yenebilir', ['Yalnızca bayramlarda yenebilir', 'Yalnızca hahamın kendi eliyle kestiği hayvanlardan elde edilir', 'Mayalı olduğu için belli günlerde yasaktır'], 'Parve (pareve) yiyecekler, örneğin balık, yumurta, meyve ve sebzeler, et ya da süt sayılmadığı için her iki grupla da tüketilebilir.'),
  ('Yahudi dinî düşüncesinde 13 inanç ilkesini derleyen ve \'Şaşkınlara Rehber\' adlı eseri yazan Endülüslü düşünür kimdir?', 'Musa ibn Meymun', ['Baal Şem Tov', 'Spinoza', 'Rabbi Akiva'], '12. yüzyılda Kurtuba\'da doğup Mısır\'da yaşayan Maimonides, 13 inanç ilkesini ve Aristotelesçi felsefeyle Yahudi inancını uzlaştırmaya çalışan \'Delâletü\'l-Hâirîn\'i yazmıştır.'),
  ('Sinagogda Tora tomarlarının saklandığı, genellikle Kudüs yönündeki duvara yerleştirilen dolaba ne ad verilir?', 'Kutsal Sandık (Aron ha-Kodeş)', ['Bima', 'Mikve', 'Menora (şamdan)'], 'Aron ha-Kodeş, Tora tomarlarının saklandığı süslü dolaptır; önünde çoğunlukla bir perde (parohet) bulunur.'),
  ('Bugün birçok kilisede ayinlerde okunan ve \'Bir olan Tanrı\'ya inanıyorum\' diye başlayan inanç bildirgesinin temeli hangi konsillerde atılmıştır?', '325 İznik ve 381 İstanbul konsillerinde', ['1054 Roma ve 1204 İstanbul toplantılarında', '1545 Trento ve 1870 Vatikan konsillerinde', '1517 Wittenberg ve 1530 Augsburg toplantılarında'], 'Nicea-Konstantinopolis İnanç Bildirgesi 325\'te İznik\'te hazırlanmış, 381 İstanbul Konsili\'nde genişletilmiştir.'),
  ('1054 ayrılığına yol açan öğreti tartışmalarından biri olan \'Filioque\' meselesi neyle ilgilidir?', 'Kutsal Ruh\'un yalnız Baba\'dan mı yoksa Oğul\'dan da mı çıktığıyla', ['Ayinlerde mayalı ya da mayasız ekmek kullanılıp kullanılmayacağıyla', 'Paskalya\'nın hangi tarihte kutlanacağıyla', 'Papaların evlenip evlenemeyeceği ile'], 'Batı kilisesi inanç bildirgesine \'ve Oğul\'dan\' (filioque) ifadesini eklemiş, Doğu kilisesi bunu kabul etmemiştir.'),
  ('Ortodoks kiliselerinde din adamlarının evliliğine ilişkin geleneksel kural hangisidir?', 'Evli bir erkek rahip olabilir ama piskopos yalnız bekâr keşişlerden seçilir', ['Hiçbir din adamı evlenemez', 'Yalnız piskoposlar evlenebilir', 'Rahipler ancak kırk yaşından sonra ve piskopos izniyle evlenebilir'], 'Ortodoks gelenekte rahipliğe atanmadan önce evlenmiş erkekler rahip olabilir; piskoposlar ise bekâr keşişler arasından seçilir.'),
  ('Kilisenin piskoposlar yerine seçilmiş ihtiyarlar (presbiterler) kurulunca yönetilmesini benimseyen, İskoçya\'da güçlü olan Kalvinist kilise hangisidir?', 'Presbiteryen Kilisesi', ['Anglikan Kilisesi', 'Metodist Kilisesi', 'Luteryen Kilisesi'], 'Presbiteryen kilise, adını Yunanca \'ihtiyar\' anlamındaki presbyteros sözcüğünden alır; John Knox İskoçya\'da bu kiliseyi kurmuştur.'),
  ('Ortaçağ\'ın en etkili düşünürlerinden Thomas Aquinas hangi tarikatın üyesiydi?', 'Dominiken', ['Fransisken', 'Cizvit', 'Benedikten'], 'Thomas Aquinas, vaaz ve öğretimi öne çıkaran Dominiken tarikatına mensuptu; \'Summa Theologiae\' adlı eseriyle Aristoteles felsefesini Hristiyan düşüncesiyle birleştirmiştir.'),
  ('Doğu\'da 4. yüzyılda Mısır çöllerinde ortaya çıkan Hristiyan keşişliğinin öncüsü sayılan kişi kimdir?', 'Büyük Antonius', ['Aziz Nikolaos', 'Aziz Benedictus', 'Aziz Augustinus'], 'Büyük Antonius (Mısırlı Antuan), çölde inzivaya çekilerek Hristiyan keşişliğinin ilk örneklerinden birini vermiştir.'),
  ('Kur\'an surelerinin \'Mekki\' ve \'Medeni\' olarak ayrılmasının ölçütü nedir?', 'Hicretten önce mi sonra mı indiğine göre', ['Sureyi ilk okuyan sahabenin nereli olduğuna göre', 'Surenin uzunluğuna göre', 'Surenin Mekke\'de mi Medine\'de mi yazıya geçirildiğine göre'], 'Yaygın kabule göre hicretten önce inen sureler Mekki, sonra inenler Medeni sayılır; Mekki sureler daha çok inanç, Medeni sureler toplumsal düzenlemeler içerir.'),
  ('İslam hukukunda Kur\'an ve sünnetten sonra gelen kaynaklardan \'icma\' neyi ifade eder?', 'Bir konuda müçtehit âlimlerin görüş birliğini', ['Benzer durumlar arasında akıl yürüterek hüküm çıkarmayı', 'Kişisel kanaate göre fetva vermeyi', 'Yerel örfü dinî hüküm saymayı'], 'İcma, belli bir dönemde müçtehitlerin bir hüküm üzerinde birleşmesidir; benzerlikten hareketle hüküm çıkarmaya ise kıyas denir.'),
  ('İslam hukukunda Kur\'an ve sünnette açık hükmü bulunmayan bir konuda, benzer bir durumdaki hükmün ortak gerekçesi üzerinden sonuca varmaya ne ad verilir?', 'Kıyas', ['İcma', 'Tefsir', 'İsnad'], 'Kıyas, hakkında hüküm bulunan bir durumla hükmü bilinmeyen bir durum arasındaki ortak gerekçeye (illet) dayanarak hüküm çıkarma yöntemidir.'),
  ('Mazeretsiz bozulan bir Ramazan orucu için verilen ağır yaptırım, Hanefi fıkhına göre çoğunlukla nasıl yerine getirilir?', 'Ardı ardına altmış gün oruç tutarak', ['Bir gün fazladan namaz kılarak', 'Yalnız bir koyun kurban ederek', 'Yalnız tövbe ve istiğfar duası okuyarak'], 'Hanefi fıkhında kasten bozulan Ramazan orucu için kefaret, kesintisiz altmış gün oruçtur; buna gücü yetmeyen altmış yoksulu doyurur.'),
  ('Hz. Ali ile Hz. Aişe\'nin taraftarları arasında 656\'da yaşanan savaş neden \'Cemel Vakası\' diye anılır?', 'Hz. Aişe\'nin savaşı bir devenin üzerindeki mahfeden izlemesi', ['Savaşın Cemel adlı bir kalede yapılması', 'Savaşta ilk kez develi süvarilerin kullanılması', 'Savaştan sonra deve kurban edilmesi'], 'Cemel Arapçada \'deve\' demektir; savaş adını Hz. Aişe\'nin bindiği deveden almıştır.'),
  ('Yemen\'de yaygın olan, beşinci imam olarak Zeyd bin Ali\'yi kabul eden Şii kol hangisidir?', 'Zeydiyye', ['İsmailiyye', 'İsna Aşeriyye', 'Nizariyye'], 'Zeydiler, imamlığı Hz. Ali\'nin torunu Zeyd bin Ali\'ye bağlar; Şii kollar içinde Sünniliğe en yakın sayılır ve Yemen\'de yaygındır.'),
  ('Tasavvufta \'fena fillah\' kavramı neyi anlatır?', 'Kişinin benliğini Allah\'ta yok etmesini', ['Bir dervişin tekkeden kovulmasını', 'Tarikata yeni giren müridin ilk dersini', 'Ölen bir şeyhin yerine halife atanmasını'], 'Fena fillah, sufinin kendi benliğinden geçip Allah\'ın varlığında yok olması anlamına gelen manevi mertebedir.'),
  ('Hacı Bektaş-ı Veli\'ye atfedilen ve tasavvuftaki manevi yolculuğun aşamalarını anlatan \'Dört Kapı Kırk Makam\' öğretisinde dört kapı hangileridir?', 'Şeriat, tarikat, marifet, hakikat', ['İman, ibadet, ahlak ve muamelat', 'Tevhit, nübüvvet, imamet, ahiret', 'Sabır, şükür, tevekkül, rıza'], 'Dört kapı şeriat, tarikat, marifet ve hakikattir; her kapının onar makamı olduğu için öğreti \'kırk makam\' olarak anılır.'),
  ('Bektaşi geleneğinde evlenmeyeceğine söz veren dervişlere ne ad verilir?', 'Mücerret', ['Muhip', 'Âşık', 'Talip'], 'Balım Sultan\'ın düzenlemesiyle Bektaşilikte evlenmeme yemini eden dervişlere mücerret denir; bu kol \'mücerretler\' olarak da anılır.'),
  ('Yesevi dervişlerinin Anadolu\'ya gelip yerleşmesi ve tekkeler açması Türk dinî tarihinde nasıl bir etki yaratmıştır?', 'Tasavvufi İslam\'ın halka yayılmasını ve Türkçe dinî şiirin gelişmesini sağlamıştır', ['Anadolu\'da tasavvufun tamamen yasaklanmasına yol açmıştır', 'Arapçanın halk dili hâline gelmesine neden olmuştur', 'Tarikatların yalnız saray çevresinde kalmasına ve halktan kopmasına neden olmuştur'], 'Horasan erenleri olarak anılan dervişler köylerde tekkeler kurmuş, Türkçe şiirle halka seslenmiş; Bektaşilik ve Alevilik bu mirastan beslenmiştir.'),
  ('Ezidi inancında Tanrı\'nın dünyayı emanet ettiği yedi melekten en önde geleni olan ve tavus kuşuyla simgelenen varlık hangisidir?', 'Melek Tavus', ['Cebrail', 'Ahura Mazda', 'Şeyh Adi'], 'Ezidi inancında Melek Tavus, yedi meleğin başıdır ve tavus kuşuyla simgelenir.'),
  ('Lübnan, Suriye ve İsrail\'de yaşayan, inanç esaslarını yalnız kendi içinden belli kişilere açan ve din değiştirmeyi kabul etmeyen topluluk hangisidir?', 'Dürziler', ['Kıptiler', 'Maruniler', 'Ezidiler'], 'Dürzilik 11. yüzyılda Mısır\'da Fatımi çevresinden doğmuştur; öğretilerin ayrıntıları yalnız \'ukkal\' denilen bilenlere açılır, dışarıdan topluluğa katılım kabul edilmez.'),
  ('Bahai inancının dünya merkezi ve Bab\'ın türbesi hangi şehirdedir?', 'Hayfa', ['Tahran', 'Bağdat', 'Edirne'], 'Bahai dünya merkezi, Karmel Dağı yamacındaki teraslı bahçeleriyle bilinen Hayfa\'dadır; Bahaullah\'ın türbesi ise yakındaki Akka\'dadır.'),
  ('Bahailiğin kurucusu Bahaullah\'ın sürgün yıllarında bir süre yaşadığı Türkiye şehri hangisidir?', 'Edirne', ['Bursa', 'Trabzon', 'Kayseri'], 'Bahaullah Bağdat\'tan İstanbul\'a, oradan Edirne\'ye (1863-1868) sürülmüş, ardından Akka\'ya gönderilmiştir.'),
  ('Vaftizci Yahya\'yı en önemli peygamber sayan, akarsuda sık sık vaftiz yapan ve özellikle Irak ile İran\'da yaşamış küçük topluluk hangisidir?', 'Mandeiler', ['Dürziler', 'Ezidiler', 'Samiriler'], 'Mandeiler Vaftizci Yahya\'yı en büyük peygamber kabul eder; ritüellerinin merkezinde akan suda vaftiz vardır.'),
  ('Kutsal dağları Kudüs değil Gerizim Dağı olan, yalnız Tora\'nın kendi versiyonunu kabul eden ve bugün birkaç yüz kişiyle yaşayan topluluk hangisidir?', 'Samiriler', ['Karaylar', 'Mandeiler', 'Esseniler'], 'Samiriler, İsrailoğullarının kuzey kabilelerinden geldiklerine inanır; Nablus yakınındaki Gerizim Dağı\'nı kutsal sayarlar ve sayıları bugün birkaç yüz kişidir.'),
  ('Zerdüştlüğün Yahudilik ve Hristiyanlık üzerinde etkili olduğu düşünülen kavramlar hangi gruptadır?', 'Son yargı, cennet-cehennem ve kurtarıcı beklentisi', ['Reenkarnasyon ve kast düzeni', 'Ataların ruhuna tapınma, totem ve tabu anlayışı', 'Yin-yang ve wu wei'], 'Birçok din tarihçisi, Babil sürgünü sonrası Pers etkisiyle son yargı, ölümden sonra ödül-ceza ve kurtarıcı (Saoshyant) beklentisi gibi kavramların gelişmesine Zerdüştlüğün katkıda bulunduğunu düşünür.'),
  ('Maniheist Uygurların yerleşik yaşama geçişini destekleyen dinî kural hangisidir?', 'Canlı öldürmenin ve et yemenin hoş görülmemesi', ['Göçebe hayatın kutsal sayılması', 'At kurban etmenin her bayramda zorunlu tutulması', 'Savaşmanın ibadet sayılması'], 'Maniheizmin seçkin mensuplara et yemeyi ve canlı öldürmeyi yasaklaması, hayvancılığa dayalı göçebe yaşamdan tarıma ve kentli yaşama geçişi desteklemiştir.'),
  ('Roma ordusunda yaygınlaşan, yeraltı tapınaklarında yalnız erkeklerin katıldığı ve boğa kurban eden tanrı tasvirleriyle bilinen gizem dini hangisidir?', 'Mitraizm', ['Maniheizm', 'Zerdüştlük', 'Gnostisizm'], 'Mitraizm, Mitras adlı tanrıya adanmış gizem diniydi; tapınakları (mithraeum) mağarayı andıran yeraltı salonlarıydı ve kült özellikle askerler arasında yayılmıştı.'),
  ('Erken dönemde bazı gruplar, maddi dünyanın düşük bir yaratıcının eseri olduğunu ve ruhun ancak seçkinlere açılan gizli bir bilgiyle kurtulabileceğini öğretiyordu. Bu akımlara ne ad verilir?', 'Gnostisizm', ['Agnostisizm', 'Stoacılık', 'Pietizm'], 'Gnostisizm adını Yunanca \'bilgi\' anlamındaki gnosis\'ten alır; maddeyi düşük ya da kötü sayıp ruhun gizli bilgiyle kurtulacağını savunur.'),
  ('Sina Dağı\'ndaki Aziz Katerina Manastırı\'nda 19. yüzyılda bulunan ve Yeni Ahit\'in eksiksiz en eski nüshasını içeren 4. yüzyıl yazması hangisidir?', 'Codex Sinaiticus', ['Codex Vaticanus', 'Ölü Deniz Yazmaları', 'Kellsli Kitap'], 'Codex Sinaiticus\'u Konstantin von Tischendorf 1844 ve 1859\'da manastırda bulmuştur; Yeni Ahit\'in eksiksiz en eski el yazmasıdır.'),
  ('Cumhuriyet\'in ilk yıllarında TBMM kararıyla görevlendirilip \'Hak Dini Kur\'an Dili\' adlı Türkçe tefsiri yazan âlim kimdir?', 'Elmalılı Hamdi Yazır', ['Mehmet Akif Ersoy', 'Ahmed Cevdet Paşa', 'Said Halim Paşa'], 'Elmalılı Hamdi Yazır, TBMM\'nin 1925 kararı üzerine Diyanet tarafından görevlendirilmiş ve dokuz ciltlik \'Hak Dini Kur\'an Dili\' tefsirini yazmıştır; meal görevini başta Mehmet Akif üstlenmiş, sonra bırakmıştır.'),
  ('Upanişadlarda bireysel öz (atman) ile evrensel mutlak gerçeklik arasındaki ilişkiye dair öne çıkan düşünce hangisidir?', 'Atmanın özünde Brahman ile bir olduğu', ['Atmanın her doğumda yok olup yeniden yaratıldığı', 'Brahman\'ın yalnız rahiplerde bulunduğu', 'Atmanın tanrıların kölesi olduğu'], 'Upanişadlar, \'Tat tvam asi\' (Sen O\'sun) gibi sözlerle bireysel özün (atman) evrensel gerçeklikle (Brahman) özdeş olduğunu öğretir.'),
  ('Hindistan\'da 1950 anayasasıyla kast temelli ayrımcılığın yasaklanmasında önemli rol oynayan, kendisi de \'dokunulmaz\' sayılan topluluktan gelen hukukçu kimdir?', 'B. R. Ambedkar', ['Jawaharlal Nehru', 'Rabindranath Tagore', 'Swami Vivekananda'], 'Bhimrao Ramji Ambedkar anayasa taslak komitesine başkanlık etmiş, dokunulmazlığı yasaklayan maddelerin yazılmasına öncülük etmiş ve sonradan Budizme geçmiştir.'),
  ('Budizmin \'anatta\' (anatman) öğretisi neyi savunur?', 'Kalıcı ve değişmez bir benliğin olmadığını', ['Her canlının ölümsüz ve değişmez bir ruhu olduğunu', 'Tanrıların insan biçiminde olduğunu', 'Evrenin sonsuza dek aynı kalacağını'], 'Anatta \'benlik yokluğu\' demektir; Budizm, Hindu düşüncesindeki kalıcı atman kavramından farklı olarak değişmez bir benliği kabul etmez.'),
  ('Pek çok Caynın patates, soğan ve havuç gibi kök sebzeleri yememesinin nedeni nedir?', 'Kökü sökerken bitkinin tamamının ve topraktaki küçük canlıların ölmesi', ['Kök sebzelerin kutsal sayılıp tapınaklara sunulması', 'Bu sebzelerin yalnız bayramlarda yenebilmesi', 'Kök sebzelerin kast düzeninde alt sınıflara ait sayılması'], 'Kök sebzeleri toplamak bitkiyi bütünüyle öldürür ve topraktaki sayısız küçük canlıya zarar verir; bu nedenle katı Cayn beslenmesinde yenmez.'),
  ('Caynizmin iki ana kolu hangileridir ve aralarındaki en bilinen fark nedir?', 'Digambara ve Şvetambara; keşişlerin çıplak mı beyaz giysili mi olacağı', ['Theravada ve Mahayana; Buda\'nın tanrı sayılıp sayılmayacağı', 'Sünni ve Şii; liderlik meselesi', 'Khalsa ve Sahajdhari; saçların kesilip kesilmeyeceği'], 'Digambara (\'göğü giyinen\') keşişleri mülk edinmeme gereği giysi giymez; Şvetambara (\'beyaz giyinen\') keşişleri ise beyaz giysiler giyer.'),
  ('Caynizmin evrene bakışıyla ilgili hangisi doğrudur?', 'Evrenin bir yaratıcı tanrı tarafından yaratılmadığına ve ezelî olduğuna inanılır', ['Evrenin altı günde yaratıldığına inanılır', 'Evrenin Brahma\'nın düşüyle var olduğuna inanılır', 'Evrenin yakında tamamen yok olacağına inanılır'], 'Caynizm, evreni başlangıcı ve sonu olmayan, yaratıcı bir tanrıya dayanmayan bir gerçeklik olarak görür; kurtuluşu ruhun kendi çabasına bağlar.'),
  ('Sihlerin ortak soyadı olarak erkeklerin \'Singh\', kadınların ise \'Kaur\' adını taşımasının amacı nedir?', 'Kasttan gelen soyadlarını kaldırarak eşitliği vurgulamak', ['Kişinin doğduğu köyü belirtmek', 'Evli ve bekârları ayırmak', 'Askerî rütbeyi göstermek'], 'Guru Gobind Singh, kasta işaret eden soyadları yerine herkesin \'aslan\' anlamındaki Singh ve \'prenses\' anlamındaki Kaur adlarını kullanmasını istemiştir.'),
  ('İse Büyük Tapınağı\'nın iç yapılarının her 20 yılda bir yanı başında yeniden inşa edilmesi Şinto anlayışında neyle ilişkilendirilir?', 'Arınma, yenilenme ve ustalık bilgisinin kuşaklara aktarılması', ['Depremlerde yıkılmasının zorunlu olması', 'Yalnız imparatorların doğum yıllarında tapınak yapılabileceğine inanılması', 'Eski yapıların satılarak gelir elde edilmesi'], 'Shikinen Sengu denilen bu gelenek, saflık ve yenilenme düşüncesini yansıtır ve yapım tekniklerinin her kuşakta yaşatılmasını sağlar.'),
  ('Küba\'da Yoruba inançlarının Katoliklikle kaynaşması sonucu doğan ve \'orisha\' denen ruhları Katolik azizlerle eşleştiren gelenek hangisidir?', 'Santeria', ['Vodou', 'Şinto', 'Rastafari'], 'Santeria, Yoruba orishalarını Katolik azizlerle özdeşleştirir; köle dönemindeki baskı altında inancı gizleyerek yaşatmanın bir yolu olmuştur.'),
  ('Avustralya yerlilerinin (Aborjinler) dünyanın atalar tarafından biçimlendirildiği zamanı ve bu zamanın bugünle bağını anlatan kavramın İngilizcedeki adı nedir?', 'Dreaming', ['Nirvana', 'Mana', 'Wu wei'], 'Aborjin geleneklerinde \'Dreaming\' ya da \'Dreamtime\', ata varlıkların toprağı, canlıları ve yasaları biçimlendirdiği ve hâlâ sürdüğüne inanılan kutsal zamanı anlatır.'),
  ('Tibet\'te Hindu, Budist, Cayn ve Bön geleneklerince kutsal sayılan ve hacıların çevresini yürüyerek dolaştığı dağ hangisidir?', 'Kailaş Dağı', ['Everest', 'Fuji Dağı', 'Sina Dağı'], 'Kailaş Dağı dört dinde kutsal sayılır; hacılar dağın çevresini \'kora\' denen yürüyüşle dolaşır ve zirveye tırmanılmaz.'),
  ('Sri Lanka\'da bir zirvedeki ayak izi biçimli oyuğu Budistlerin Buda\'ya, Hinduların Şiva\'ya, bazı Müslüman ve Hristiyanların ise Âdem\'e ait saydığı dağ hangisidir?', 'Adem Tepesi', ['Kailaş Dağı', 'Fuji Dağı', 'Arunaçala'], 'Adem Tepesi\'ndeki kaya oyuğu farklı dinlerce farklı biçimlerde kutsanır; bu da ortak kutsal mekânların ilginç bir örneğidir.'),
  ('Bir tapınak kompleksinde Şinto tapınağına \'jinja\', Budist tapınağına ise \'tera\' denen ülke hangisidir?', 'Japonya', ['Çin', 'Tayland', 'Hindistan'], 'Japoncada Şinto tapınakları jinja ya da -gū/-taisha, Budist tapınakları ise tera ya da -ji ekiyle anılır; örneğin Todai-ji.'),
  ('Hristiyanlıkta en yaygın simge olan haçın Ortodoks geleneğinde sık görülen biçimi hangi özelliği taşır?', 'Ana çubuğa ek olarak üstte ve altta birer kısa çubuk bulunması', ['Dört kolunun uçlarının çatallı olması ve ortasında bir daire bulunması', 'Yalnız dikey çubuktan oluşması', 'Ters çevrilmiş olarak kullanılması'], 'Rus Ortodoks haçında üstte yazıt levhasını, altta eğik ayak dayanağını simgeleyen ek çubuklar bulunur.'),
  ('Kapadokyalı üç kilise babası (Büyük Basileios, Nazianzoslu Gregorios, Nyssalı Gregorios) Hristiyan düşüncesine hangi alanda katkılarıyla bilinir?', 'Teslis öğretisinin ve Doğu keşiş yaşamının biçimlenmesi', ['Kutsal Kitap\'ın Latinceye çevrilmesi', 'Protestan Reformu\'nun ilk tezlerinin yazılması ve yayılması', 'Papalığın kurulması'], '4. yüzyılda yaşayan Kapadokya Babaları Teslis öğretisinin netleşmesine katkı sağlamış, Basileios ise Doğu manastır kurallarını düzenlemiştir.'),
  ('922\'de Abbasi halifesinin elçilik heyetiyle Volga Bulgarlarına giderek gözlemlerini yazıya geçiren seyyah kimdir?', 'İbn Fadlan', ['İbn Battuta', 'Evliya Çelebi', 'Marco Polo'], 'İbn Fadlan\'ın seyahatnamesi, Volga Bulgarlarının İslam\'ı kabulü ile Oğuz ve Hazarların gelenekleri hakkında değerli bilgiler içerir.'),
  ('Göktürk Kağanı Taspar (Tatpar) Kağan\'ın döneminde Türkler arasında yayılmaya çalışılan ve kağanın bir tapınak yaptırdığı anlatılan din hangisidir?', 'Budizm', ['Maniheizm', 'Hristiyanlık', 'Zerdüştlük'], 'Çin kaynaklarına göre Taspar Kağan Budizme ilgi duymuş, bir Budist tapınağı yaptırmış ve Budist metinlerin Türkçeye çevrilmesini istemiştir.'),
  ('14. yüzyıldan kalan ve Kıpçak Türkçesiyle yazılmış Hristiyan ilahileri ile sözlük içeren ünlü yazma hangisidir?', 'Codex Cumanicus', ['Divanü Lügati\'t-Türk', 'Kutadgu Bilig', 'Atabetü\'l-Hakayık'], 'Codex Cumanicus, İtalyan tüccarlar ve Fransisken misyonerlerin Kırım\'da hazırladığı, Kuman-Kıpçak Türkçesi sözlük ve dinî metinler içeren yazmadır.'),
  ('Rusya Federasyonu içindeki Saha (Yakut) ve Altay gibi Türk halkları arasında hangi inanç gelenekleri bugün de kısmen yaşamaktadır?', 'Şamanist ve doğa merkezli eski inançlar', ['Sihizm', 'Zerdüştlük', 'Caynizm'], 'Saha ve Altay Türkleri arasında Ortodoksluğun yanında şamanizm ve Aar Ayıı, Burhanizm gibi yerli inanç gelenekleri sürmektedir.'),
  ('Türklerin büyük çoğunluğunun İslam\'ı kabul etmesinde 751 Talas Savaşı\'nın etkisi en iyi nasıl açıklanır?', 'Abbasilerle yakınlaşmayı başlatıp İslam\'ın Türkler arasında yayılmasını kolaylaştırması', ['Türklerin tamamının aynı gün Müslüman olması', 'Talas\'ta ilk Türkçe Kur\'an tefsirinin yazılması', 'Savaşın ardından Budizmin Orta Asya\'da güç kazanması'], 'Talas\'ta Karluklar Abbasilerin yanında yer almış, Çin\'in Orta Asya\'daki etkisi zayıflamış ve İslam\'ın Türkler arasında yayılmasının önü açılmıştır.'),
  ('Fatih Sultan Mehmet\'in İstanbul\'un fethinden sonra Rum Ortodoks patriği olarak atadığı din adamı kimdir?', 'Gennadios Scholarios', ['Ioannes Khrysostomos', 'Photios', 'Mikhail Kerularios'], 'Fatih 1454\'te Gennadios Scholarios\'u patrik olarak atamış ve patrikhaneye geniş dinî ve hukuki yetkiler tanımıştır.'),
  ('Osmanlı padişahlarının halife unvanını resmî belgelerde belirgin biçimde kullanmasına dayanak olarak gösterilen 1774 tarihli antlaşma hangisidir?', 'Küçük Kaynarca Antlaşması', ['Karlofça Antlaşması', 'Pasarofça Antlaşması', 'Yaş Antlaşması'], 'Küçük Kaynarca\'da Kırım\'ın bağımsızlığı kabul edilirken padişahın halife sıfatıyla Kırım Müslümanlarının dinî önderi olduğu belirtilmiştir.'),
  ('Bir felsefe öğrencisi, büyük bir depremde masum insanların ölmesini, iyi ve her şeye gücü yeten bir Tanrı inancıyla nasıl bağdaştırabileceğini soruyor. Bu soru hangi tartışmanın konusudur?', 'Teodise', ['Eskatoloji', 'Ontoloji', 'Kozmoloji'], 'Teodise (\'Tanrı\'nın adaleti\') terimini Leibniz yaygınlaştırmıştır; kötülük problemine verilen savunmaları kapsar.'),
  ('Katolik ve Ortodoks Kutsal Kitaplarında Eski Ahit\'te bulunup Protestan Kutsal Kitaplarında genellikle bulunmayan (ya da ayrı tutulan) kitaplara ne ad verilir?', 'Deuterokanonik kitaplar', ['Sinoptik İnciller', 'Pastoral mektuplar', 'Mezmurlar'], 'Tobit, Yudit ve Makabeler gibi kitaplar Katolik ve Ortodoks kanonunda yer alır; Protestanlar bunları İbranice Tanah\'ta bulunmadığı için kanon dışı sayar.'),
  ('Bir araştırmacı, bir kutsal metnin yazıldığı tarihsel bağlamı, dilini ve okuyucunun yorumu nasıl etkilediğini inceleyerek metnin nasıl anlaşılması gerektiğine dair ilkeler geliştiriyor. Bu araştırmacının çalıştığı alan hangisidir?', 'Hermenötik', ['Eskatoloji', 'Apologetik', 'Liturji'], 'Hermenötik, Yunanca \'yorumlamak\' anlamındaki hermeneuein\'den gelir; adını tanrıların ulağı Hermes\'le ilişkilendiren bir açıklama da vardır.'),
  ('Katolik Kilisesi\'nde evlilik nasıl değerlendirilir?', 'Kutsal bir sakrament ve çözülmez bir bağ olarak', ['Yalnız resmî bir sözleşme olarak', 'Din adamlarına özgü bir yemin olarak', 'Sadece medeni nikâhla geçerli sayılan bir tören olarak'], 'Katolik Kilisesi evliliği sakrament sayar ve boşanmayı kabul etmez; yalnız evliliğin baştan geçersiz olduğunu tespit eden iptal yoluna izin verir.'),
  ('Ortodoks Hristiyanlıkta ikonalar hangi anlayışla kullanılır?', 'Tasvir edilen kişiye saygının aracı olarak; tasvire tapınılmaz', ['Kendilerine doğrudan tapınılan tanrısal nesneler olarak', 'Yalnız kiliseleri süslemek için yapılmış, dinî anlamı olmayan resimler olarak', 'Kilise dışında kullanılması yasak tablolar olarak'], '843\'te teyit edilen öğretiye göre ikonaya gösterilen saygı tasvir edilen kişiye yönelir; tapınma yalnız Tanrı\'ya özgüdür.'),
  ('Süleyman Çelebi\'nin yazdığı ve halk arasında \'Mevlid\' olarak bilinen eserin özgün adı nedir?', 'Vesiletü\'n-Necat', ['Mesnevi', 'Divan-ı Hikmet', 'Muhammediye'], 'Süleyman Çelebi\'nin 1409\'da Bursa\'da yazdığı \'Vesiletü\'n-Necat\' (kurtuluş vesilesi), Hz. Muhammed\'in doğumunu anlatır ve halk arasında Mevlid olarak bilinir.'),
  ('Bir Theravada Budist keşişinin geleneksel olarak sabah dilenerek yiyecek toplaması ve öğleden sonra katı yemek yememesi hangi anlayışı yansıtır?', 'Sadelik, bağımlılıktan uzak durma ve toplulukla bağ', ['Keşişlerin zengin olması gerektiği', 'Yemeğin önce kutsal bir hayvana sunulması gerektiği inancı', 'Keşişlerin yemek pişirmeyi bilmemesi'], 'Keşişler mülk edinmez, halkın sunduğu yiyecekle yaşar; halk da sunu yoluyla erdem kazandığına inanır. Öğleden sonra yememek Vinaya kurallarındandır.'),
  ('Varlığın özünde tek olduğunu ve her şeyin Tanrı\'nın tecellisi olduğunu öne süren \'vahdet-i vücud\' anlayışı en çok hangi düşünürle ilişkilendirilir?', 'Muhyiddin İbnü\'l-Arabi', ['İmam Gazali', 'İmam Rabbani', 'Ebu Hanife'], 'Endülüslü İbnü\'l-Arabi, \'Fütuhat-ı Mekkiyye\' ve \'Fususü\'l-Hikem\' gibi eserleriyle vahdet-i vücud anlayışının en önemli temsilcisi sayılır; türbesi Şam\'dadır.'),
  ('Cennet umudu ya da cehennem korkusu için değil, yalnızca Allah sevgisi için ibadet edilmesi gerektiğini söyleyen erken dönem kadın sufi kimdir?', 'Rabiatü\'l-Adeviyye', ['Hz. Hatice', 'Nefise Hatun', 'Hz. Fatıma'], '8. yüzyılda Basra\'da yaşayan Rabiatü\'l-Adeviyye, ilahi aşk anlayışını tasavvufa yerleştiren öncülerden biri kabul edilir.'),
  ('17. yüzyılda Hindistan\'da yaşayan, \'müceddid-i elf-i sânî\' (ikinci bin yılın yenileyicisi) olarak anılan ve \'vahdet-i şuhud\' anlayışını savunan Nakşibendi âlim kimdir?', 'İmam Rabbani', ['İbnü\'l-Arabi', 'Şah Veliyyullah', 'Mevlânâ Halid'], 'Ahmed Sirhindi (İmam Rabbani), \'Mektubat\' adlı eseriyle tanınır ve Nakşibendiliğin Müceddidi kolunun kurucusu sayılır.'),
  ('Zikir sırasında yüksek sesle ve coşkuyla zikreden, bazı törenlerinde şiş gibi keskin aletlerle gösteriler yapmasıyla bilinen tarikat hangisidir?', 'Rifailik', ['Nakşibendilik', 'Melamilik', 'Bayramilik'], 'Ahmed er-Rifai\'ye nispet edilen Rifailik, sesli zikri ve \'burhan\' denilen olağanüstü gösterileriyle tanınır.'),
  ('Süleyman\'ın ölümünden sonra İsrail krallığının bölünmesiyle oluşan iki krallık hangileridir?', 'Kuzeyde İsrail, güneyde Yehuda', ['Kuzeyde Babil, güneyde Mısır', 'Kuzeyde Fenike, güneyde Filistin', 'Kuzeyde Asur, güneyde Edom'], 'Krallık kuzeyde başkenti Samiriye olan İsrail ile güneyde başkenti Kudüs olan Yehuda olarak ikiye ayrılmıştır; \'Yahudi\' adı Yehuda\'dan gelir.'),
  ('Ortaçağ İspanya\'sında zorla Hristiyanlaştırılan ve gizlice Yahudi inancını sürdürdüğü düşünülen kişilere ne ad verilmiştir?', 'Conversos (Maranolar)', ['Moriskolar (dönme Müslümanlar)', 'Mozaraplar', 'Mudejarlar'], 'Hristiyanlığa geçmeye zorlanan Yahudilere \'conversos\', gizlice Yahudiliği sürdürdüğü düşünülenlere küçümseyici biçimde \'marrano\' denmiş; Müslümanlardan geçenler ise morisko olarak anılmıştır.'),
  ('Bir kilisede, İsa\'nın çarmıha giderken yaşadıklarını anlatan on dört sahneden oluşan resim ya da kabartma dizisi bulunuyor. Bu diziye ne ad verilir?', 'Çarmıh Yolu istasyonları', ['İkonostasis', 'Vitray', 'Triptik'], 'Katolik kiliselerinde Çarmıh Yolu\'nun on dört istasyonu duvarlara dizilir; inananlar özellikle perhiz döneminde bu istasyonlarda dua eder.'),
  ('Osmanlı padişahlarının tahta çıkışlarında kılıç kuşanma töreninin yapıldığı yer hangisiydi?', 'Eyüp Sultan Türbesi ve Camii', ['Ayasofya', 'Topkapı Sarayı Bâbüssaade', 'Süleymaniye Camii'], 'Kılıç kuşanma töreni, yeni padişahın Eyüp Sultan\'a giderek kılıç kuşanmasıyla yapılırdı; törenin sahabenin türbesinde yapılması meşruiyeti pekiştirirdi.'),
  ('Manisa\'nın Salihli ilçesindeki antik Sardes kentinde bulunan büyük sinagog hangi bakımdan önemlidir?', 'Antik dünyanın bilinen en büyük sinagoglarından biri olmasıyla', ['İlk Hristiyan kilisesi olmasıyla', 'Yeni Ahit\'in burada yazılmasıyla', 'Ortaçağ\'da cami olarak kullanılan ilk yapı olmasıyla'], 'Sardes Sinagogu, Roma döneminde büyük bir yapının sinagoga dönüştürülmesiyle oluşmuş; antik dönemin bilinen en büyük sinagoglarındandır ve Anadolu\'daki köklü Yahudi varlığını gösterir.'),
  ('Kars yakınlarındaki Ani Ören Yeri\'nde bulunan Ebu\'l-Menuçehr Camii hangi özelliğiyle bilinir?', 'Anadolu\'da Türklerin yaptığı ilk camilerden biri sayılmasıyla', ['Dünyanın en büyük kubbesine sahip olmasıyla', 'Ahşap direkli tek cami olmasıyla', 'İçinde Mevlânâ\'nın türbesi bulunmasıyla'], '11. yüzyılda Şeddadiler döneminde yapılan Ebu\'l-Menuçehr Camii, Anadolu\'daki en eski Türk camilerinden kabul edilir; Ani aynı zamanda çok sayıda Ermeni kilisesinin bulunduğu bir ortaçağ kentidir.'),
  ('İznik\'in (Nikaia) Hristiyanlık tarihindeki önemi en iyi nasıl özetlenir?', '325 ve 787\'de iki ekümenik konsile ev sahipliği yapmıştır', ['Hristiyanlığın ilk kez burada vaaz edildiği şehirdir', 'Papalığın ilk merkezi olmuştur', 'Yeni Ahit\'in burada derlendiği kabul edilir'], 'İznik\'te 325\'te birinci, 787\'de ise ikonaların kullanımını onaylayan yedinci ekümenik konsil toplanmıştır.'),
  ('Tarih öncesi mağara resimlerinin bir kısmının avda başarı için yapılmış büyüsel ya da ritüel resimler olduğunu öne süren yorum hangi kavrama dayanır?', 'Av büyüsü', ['Monoteizm', 'Hiyerofani', 'Teodise'], 'Av büyüsü yorumu, hayvan resimlerinin avı kolaylaştıracağına inanılarak yapıldığını öne sürer; Lascaux gibi mağaralar için önerilmiş, ancak tek açıklama olarak kabul görmez.'),
  ('Bir öğrenci, \'Bu dinde kurtuluş, tanrının lütfuyla değil kişinin kendi çabasıyla, ruhu karma maddesinden arındırarak elde edilir; evren yaratılmamıştır.\' notunu alıyor. Not hangi dine aittir?', 'Caynizm', ['Sihizm', 'Zerdüştlük', 'Yahudilik'], 'Caynizm yaratıcı bir tanrı kabul etmez; ruhun katı ahimsa ve çilecilikle karmadan arınarak kurtulacağını öğretir.'),
  ('Bir din tarihçisi, Yahudilik, Hristiyanlık ve İslam\'ı \'zaman doğrusal ilerler, tarihin bir başı ve sonu vardır\' anlayışıyla; Hinduizm ve Budizmi ise \'döngüsel zaman\' anlayışıyla tanımlıyor. Bu ayrımın en belirgin yansıması hangisidir?', 'İbrahimî dinlerde son yargı, Hint dinlerinde ise yeniden doğuş döngüsü inancı', ['İbrahimî dinlerde keşişliğin, Hint dinlerinde evliliğin yasak olması', 'İbrahimî dinlerde tapınak olmaması', 'Hint dinlerinde kutsal metin bulunmaması'], 'Doğrusal zaman anlayışı tarihin kıyamet ve son yargıyla sona ereceği inancına; döngüsel zaman anlayışı ise samsara ve çağların tekrar etmesi düşüncesine bağlanır.'),
  ('Japonya\'da yaygın olan ve Amida Buda\'nın adını içtenlikle anarak onun \'Saf Toprak\' adlı cennetinde yeniden doğmayı amaçlayan Budist okul hangisidir?', 'Saf Toprak (Jodo) Budizmi', ['Zen Budizmi', 'Theravada', 'Tibet Budizmi'], 'Saf Toprak Budizmi, \'Namu Amida Butsu\' sözünü tekrarlayarak Amida Buda\'nın merhametine sığınmayı öğütler; Japonya\'nın en yaygın Budist okullarındandır.'),
  ('Bir Hindu düşünce okulu olan Advaita Vedanta\'nın temel tezi hangisidir?', 'Gerçekte yalnız Brahman vardır; çokluk görünüşten (maya) ibarettir', ['Ruh ile madde ezelden beri ayrı ve bağımsızdır', 'Tanrı yoktur, yalnız atomlar vardır', 'Her canlının ayrı ve ölümsüz bir bedeni vardır'], '8. yüzyılda Şankara\'nın sistemleştirdiği Advaita (\'ikiliksizlik\') Vedanta, yalnız Brahman\'ın gerçek olduğunu ve atman ile Brahman\'ın özdeşliğini savunur.'),
  ('Hinduizmde Vişnu\'ya bağlılığı esas alan geleneğe ne ad verilir?', 'Vaişnavizm', ['Şaivizm', 'Şaktizm', 'Smarta'], 'Vaişnavizm Vişnu ve avatarlarına, Şaivizm Şiva\'ya, Şaktizm ise tanrıçaya bağlılığı esas alan Hindu gelenekleridir.'),
  ('Hindu tasvirlerinde Şiva\'nın evrenin yaratılış ve yıkılış döngüsünü simgeleyen, ateş çemberi içinde dans eden biçimi hangi adla bilinir?', 'Nataraja', ['Ganeşa', 'Hanuman', 'Narasimha'], 'Nataraja tasviri, Şiva\'nın kozmik dansıyla evrenin yaratılması, korunması ve yok edilmesi döngüsünü simgeler; özellikle Güney Hint bronz heykelleriyle ünlüdür.'),
  ('İslam\'da yolculuk sırasında dört rekâtlı farz namazların ikişer rekât kılınabilmesine ne ad verilir?', 'Seferîlik hükmü', ['Kaza', 'Cem', 'İtikâf'], 'Seferî sayılan yolcu, öğle, ikindi ve yatsının dört rekâtlı farzlarını iki rekât olarak kılar; buna kasr denir.'),
  ('Konfüçyüsçülükte törenlere, görgü kurallarına ve uygun davranış biçimlerine uyumu anlatan kavram hangisidir?', 'Li', ['Ren', 'Wu wei', 'Qi'], 'Li, törenler, saygı ve uygun davranış kurallarını anlatır; Konfüçyüs, li\'ye uyumun toplumsal ahengi sağlayacağını düşünmüştür.'),
  ('Bir öğrenci Konfüçyüsçülüğün bir din mi yoksa bir ahlak ve yönetim felsefesi mi olduğunu tartışıyor. Bu tartışmayı doğuran en önemli özellik hangisidir?', 'Öğretinin tanrılar ve öbür dünya yerine toplumsal ilişkiler ve ahlak üzerinde yoğunlaşması', ['Hiçbir yazılı metninin bulunmaması', 'Yalnız keşişler tarafından uygulanması', 'Tek tanrıya ibadeti zorunlu tutması'], 'Konfüçyüs öbür dünya hakkında konuşmaktan kaçınmış, aile, devlet ve erdem üzerinde durmuştur; ancak atalara saygı ve törenler dinî bir boyut da taşır.'),
  ('Şinto tapınaklarında kutsal alanı ya da kutsal bir ağacı işaretlemek için gerilen kalın pirinç sapı ipine ne ad verilir?', 'Shimenawa', ['Torii', 'Omamori', 'Kagura'], 'Shimenawa, kutsal alanı belirleyen ve kötü etkileri uzak tuttuğuna inanılan örgülü pirinç sapı ipidir; genellikle beyaz kâğıt şeritlerle süslenir.'),
  ('19. yüzyıl sonunda ABD\'deki yerli halklar arasında yayılan, ataların dönüşü ve eski yaşamın yeniden kurulacağı beklentisiyle yapılan dinî hareket hangisidir?', 'Hayalet Dansı', ['Güneş Dansı', 'Potlatch', 'Ter kulübesi'], 'Paiute peygamberi Wovoka\'nın öğretilerine dayanan Hayalet Dansı, 1890 Wounded Knee katliamıyla trajik biçimde son bulmuştur.'),
  ('Etiyopya Ortodoks Kilisesi\'ne göre Ahit Sandığı\'nın saklandığı iddia edilen şehir hangisidir?', 'Aksum', ['Addis Ababa', 'Lalibela', 'Gondar'], 'Etiyopya geleneği Ahit Sandığı\'nın Aksum\'daki Siyonlu Meryem Kilisesi\'nde korunduğunu kabul eder; sandığı yalnız bir keşiş görebilir.'),
  ('Hindistan\'ın güneybatısındaki Kerala\'da yaşayan ve kökenini Havari Tomas\'a dayandıran Hristiyan topluluğa ne ad verilir?', 'Tomas Hristiyanları', ['Kıptiler', 'Maruniler', 'Nasturiler'], 'Kerala\'daki Aziz Tomas Hristiyanları, geleneğe göre Tomas\'ın 1. yüzyılda Hindistan\'a geldiğine inanır ve tarihsel olarak Süryani ayinini kullanmıştır.'),
  ('5. yüzyılda İstanbul Patriği Nestorius\'un görüşlerini izleyerek İran ve Orta Asya\'ya, hatta Çin\'e kadar yayılan Hristiyan kilisesi hangi adla anılır?', 'Doğu Kilisesi', ['Kıpti Kilisesi', 'Ermeni Kilisesi', 'Maruni Kilisesi'], 'Doğu Kilisesi Sasani İran\'ında örgütlenmiş, İpek Yolu boyunca Orta Asya ve Tang Çin\'ine kadar ulaşmış; bazı Türk ve Moğol boyları arasında da yayılmıştır.'),
  ('Geleneğe göre X biçimli bir haçta öldürüldüğüne inanılan ve İskoçya\'nın koruyucu azizi sayılan havari kimdir?', 'Andreas', ['Petrus', 'Tomas', 'Matta'], 'Geleneğe göre Andreas X biçimli haçta çarmıha gerilmiştir; bu haç \'Aziz Andreas haçı\' olarak anılır ve İskoçya\'nın koruyucu azizidir.'),
  ('1598\'de Fransa\'da Protestanlara (Hugenotlara) belirli ölçüde din özgürlüğü tanıyan ferman hangisidir?', 'Nant Fermanı', ['Milano Fermanı', 'Vormus Fermanı', 'Augsburg Barışı'], 'IV. Henri\'nin Nant Fermanı Hugenotlara ibadet ve sivil haklar tanımıştır; 1685\'te XIV. Louis tarafından kaldırılmıştır.'),
  ('1555 Augsburg Barışı\'nda kabul edilen \'cuius regio, eius religio\' ilkesi ne anlama gelir?', 'Bir bölgenin dinini o bölgenin hükümdarı belirler', ['Herkes istediği dini seçebilir', 'Papa bütün hükümdarların üstündedir', 'Kilise ile devlet tamamen ayrılmalıdır'], '\'Kimin ülkesi, onun dini\' anlamındaki ilkeyle Kutsal Roma Germen İmparatorluğu\'nda her prensin ülkesinde Katolikliği ya da Lutherciliği belirlemesi kabul edilmiştir.'),
  ('Bir gazeteci \'Budizm tanrısız bir dindir\' yazıyor. Bu ifadeyi değerlendirmek için en dengeli yaklaşım hangisidir?', 'Budizmde yaratıcı tanrı merkezde değildir; ancak bazı okullarda tanrısal varlıklar ve bodhisattvalara saygı vardır', ['İfade tamamen yanlıştır, çünkü Budizm tek tanrılı bir dindir', 'İfade tamamen doğrudur ve bütün Budist okullar için aynen geçerlidir', 'Budizm bir din değil, yalnız bir beslenme rejimidir'], 'Buda yaratıcı bir tanrıdan söz etmemiş, kurtuluşu bireysel çabaya bağlamıştır; ancak Mahayana ve Vajrayana\'da çeşitli buda, bodhisattva ve devalara ibadet edilir. Bu yüzden genelleme dikkatle yapılmalıdır.'),
  ('Yahudilikte din değiştirerek Yahudi olmak isteyen kişiye ilişkin geleneksel tutum hangisidir?', 'Mümkündür ancak dinî mahkeme önünde eğitim ve kabul süreci gerektirir', ['Yahudiliğe geçmek kesinlikle imkânsızdır', 'Yalnız yemin etmek yeterlidir', 'Yalnız Kudüs\'te doğanlar kabul edilir'], 'Yahudilik misyonerlik yapmaz, ancak ihtida mümkündür; Ortodoks gelenekte kişi eğitim alır, beth din (dinî mahkeme) önünde kabul edilir ve mikveye girer.'),
  ('Yahudilikte kimin Yahudi sayılacağına ilişkin geleneksel (Ortodoks) kural hangisidir?', 'Annesi Yahudi olan ya da usulüne göre Yahudiliğe geçen kişi', ['Yalnız babası Yahudi olan kişi', 'İsrail\'de doğan herkes', 'Sinagoga bir kez gitmiş olan herkes'], 'Geleneksel Yahudi hukukunda Yahudilik anne yoluyla geçer; Reform Yahudiliği ise bazı durumlarda baba yoluyla soyu da kabul eder.'),
  ('Avesta\'da adı geçen ve Zerdüşt geleneğinde peygamber olarak kabul edilen Zerdüşt\'ün (Zarathuştra) yaşadığı dönemle ilgili hangisi doğrudur?', 'Tarihi kesin değildir; tahminler MÖ 1500 ile MÖ 500 arasında değişir', ['Kesin olarak MS 622\'de yaşamıştır', 'Buda\'dan sonra Çin\'de yaşamıştır', 'Roma İmparatorluğu döneminde yaşamıştır'], 'Zerdüşt\'ün yaşadığı dönem tartışmalıdır; Gathaların dili Rigveda\'ya yakın olduğu için birçok uzman onu MÖ 2. binyılın sonlarına yerleştirir.'),
  ('Tibet\'in Budizm öncesi yerli geleneği olarak bilinen ve Tibet Budizmini de etkileyen inanç hangisidir?', 'Bön', ['Şinto', 'Taoizm', 'Caynizm'], 'Bön, Tibet\'in eski dinî geleneğidir; Tibet Budizmiyle uzun süre etkileşmiş ve bugün de ayrı bir gelenek olarak yaşamaktadır.'),
];
